static void addEdge(int id, int u, int v, int w) {
    adj[adjCnt].to = v;
    adj[adjCnt].w = w;
    adj[adjCnt].id = id;
    adj[adjCnt].next = head[u];
    head[u] = adjCnt++;

    adj[adjCnt].to = u;
    adj[adjCnt].w = w;
    adj[adjCnt].id = id;
    adj[adjCnt].next = head[v];
    head[v] = adjCnt++;
}

static int lexLess(int *a, int na, int *b, int nb) {
    int i, lim = na < nb ? na : nb;
    for (i = 0; i < lim; i++) {
        if (a[i] != b[i]) return a[i] < b[i];
    }
    return na < nb;
}

static void consider(int len) {
    if (len > bestLen) {
        bestLen = len;
        bestPathSize = curPathSize;
        memcpy(bestPath, curPath, sizeof(int) * curPathSize);
    } else if (len == bestLen) {
        if (bestPathSize == 0 || lexLess(curPath, curPathSize, bestPath, bestPathSize)) {
            bestPathSize = curPathSize;
            memcpy(bestPath, curPath, sizeof(int) * curPathSize);
        }
    }
}

static void dfs(int u, int len) {
    consider(len);

    for (int e = head[u]; e != -1; e = adj[e].next) {
        int id = adj[e].id;
        int v = adj[e].to;
        if (used[id]) continue;

        used[id] = 1;
        curPath[curPathSize++] = v;
        dfs(v, len + adj[e].w);
        curPathSize--;
        used[id] = 0;
    }
}

