    int n;
    cin >> n;
    vector<vector<pair<int, int>>> adj(n);
    for (int i = 0; i < n - 1; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});
    }

    // BFS to find farthest node and distances
    auto bfs = [&](int start) -> pair<vector<long long>, vector<int>> {
        vector<long long> dist(n, -1);
        vector<int> parent(n, -1);
        queue<int> q;
        dist[start] = 0;
        q.push(start);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto [v, w] : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + w;
                    parent[v] = u;
                    q.push(v);
                }
            }
        }
        return {dist, parent};
    };

    // First BFS: from node 0
    auto [dist1, _] = bfs(0);
    int farA = max_element(dist1.begin(), dist1.end()) - dist1.begin();

    // Second BFS: from farA
    auto [dist2, parent] = bfs(farA);
    int farB = max_element(dist2.begin(), dist2.end()) - dist2.begin();

    // Reconstruct path from farA to farB
    vector<int> path;
    for (int v = farB; v != -1; v = parent[v]) {
        path.push_back(v);
    }
    reverse(path.begin(), path.end());

    // Check if there is a lexicographically smaller path of same length
    // We need to consider all diameter paths.
    // Find all nodes that can be endpoints of a diameter.
    long long diameter = dist2[farB];
    vector<int> candidates;
    for (int i = 0; i < n; i++) {
        if (dist2[i] == diameter) candidates.push_back(i);
    }

    // For each candidate endpoint, reconstruct path and pick lexicographically smallest
    vector<int> bestPath = path;
    for (int end : candidates) {
        auto [d, p] = bfs(end);
        int start = max_element(d.begin(), d.end()) - d.begin();
        if (d[start] != diameter) continue;
        vector<int> cur;
        for (int v = start; v != -1; v = p[v]) {
            cur.push_back(v);
        }
        reverse(cur.begin(), cur.end());
        if (cur < bestPath) bestPath = cur;
    }

    // Output
    long long totalDist = 0;
    for (int i = 0; i + 1 < (int)bestPath.size(); i++) {
        int u = bestPath[i], v = bestPath[i+1];
        for (auto [nei, w] : adj[u]) {
            if (nei == v) {
                totalDist += w;
                break;
            }
        }
    }

    cout << totalDist << "\n";
    for (int i = 0; i < (int)bestPath.size(); i++) {
        if (i) cout << " ";
        cout << bestPath[i];
    }
    cout << "\n";

    return 0;
}

