/*
The statement provided is incomplete, so this solution targets the natural
interpretation:

- Each railway system is an undirected weighted graph.
- A valid path may start at any station.
- No edge may be used more than once.
- We want the maximum total length among all such trails.
- If multiple maximum-length trails exist, output the lexicographically
  smallest station sequence.

Input format assumed:
T
For each test case:
n m
u1 v1 w1
...
um vm wm

Stations are numbered from 1 to n.

Output for each test case:
<maximum_length>
<k> s1 s2 ... sk

where s1..sk is the chosen station sequence.

This is an exponential problem in general, so this solution is suitable for
small graphs, which is typical for this kind of task.
*/

struct Edge {
    int u, v;
    long long w;
};

int n, m;
vector<Edge> edges;
vector<vector<pair<int,int>>> adj; // (to, edge_id)

long long bestLen;
vector<int> bestPath;
vector<char> used;

bool lexicographicallySmaller(const vector<int>& a, const vector<int>& b) {
    return lexicographical_compare(a.begin(), a.end(), b.begin(), b.end());
}

void consider(const vector<int>& path, long long len) {
    if (len > bestLen) {
        bestLen = len;
        bestPath = path;
    } else if (len == bestLen) {
        if (bestPath.empty() || lexicographicallySmaller(path, bestPath)) {
            bestPath = path;
        }
    }
}

void dfs(int u, long long curLen, vector<int>& path) {
    consider(path, curLen);

    for (auto [v, id] : adj[u]) {
        if (used[id]) continue;
        used[id] = 1;
        path.push_back(v);
        dfs(v, curLen + edges[id].w, path);
        path.pop_back();
        used[id] = 0;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    if (!(cin >> T)) return 0;

    while (T--) {
        cin >> n >> m;
        edges.resize(m);
        adj.assign(n + 1, {});

        for (int i = 0; i < m; ++i) {
            int u, v;
            long long w;
            cin >> u >> v >> w;
            edges[i] = {u, v, w};
            adj[u].push_back({v, i});
            adj[v].push_back({u, i});
        }

        for (int i = 1; i <= n; ++i) {
            sort(adj[i].begin(), adj[i].end());
        }

        bestLen = -1;
        bestPath.clear();
        used.assign(m, 0);

        for (int s = 1; s <= n; ++s) {
            vector<int> path = {s};
            dfs(s, 0, path);
        }

        cout << bestLen << "\n";
        cout << bestPath.size();
        for (int x : bestPath) cout << ' ' << x;
        cout << "\n";
    }

    return 0;
}

