    static void dfs(int u, int parent, long dist, List<Integer> path) {
        if (dist > bestDist || (dist == bestDist && comparePaths(path, bestPath) < 0)) {
            bestDist = dist;
            bestPath = new ArrayList<>(path);
        }
        for (Edge e : adj.get(u)) {
            if (e.to != parent) {
                path.add(e.to);
                dfs(e.to, u, dist + e.w, path);
                path.remove(path.size() - 1);
            }
        }
    }

    static int comparePaths(List<Integer> a, List<Integer> b) {
        if (b == null) return -1;
        int len = Math.min(a.size(), b.size());
        for (int i = 0; i < len; i++) {
            if (!a.get(i).equals(b.get(i))) {
                return a.get(i) - b.get(i);
            }
        }
        return a.size() - b.size();
    }
