/*
Assumption from the statement:
- Each railway system is an undirected weighted graph.
- We need the longest trail: a path that may revisit vertices but cannot reuse an edge.
- Among multiple longest trails, output the lexicographically least station sequence.

Because the full original statement/input format is not provided here, this solution uses
a common multi-testcase format:

Input:
T
For each test case:
n m
m lines follow: u v w

Stations are assumed numbered 1..n.

Output for each test case:
<maximum total length>
<k stations of the chosen path separated by spaces>

If no edge exists, the longest path length is 0 and the lexicographically least path is [1].

This exact algorithm is exponential in the number of edges and is intended for small graphs,
which is typical for longest-trail enumeration tasks.
*/
public class Main {
    static class Edge {
        int u, v;
        long w;
        Edge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
        int other(int x) {
            return x == u ? v : u;
        }
    }

    static int n, m;
    static Edge[] edges;
    static List<Integer>[] adj;

    static long bestLen;
    static List<Integer> bestPath;

    static void dfs(int cur, boolean[] used, long len, ArrayList<Integer> path) {
        if (len > bestLen) {
            bestLen = len;
            bestPath = new ArrayList<>(path);
        } else if (len == bestLen) {
            if (bestPath == null || lexLess(path, bestPath)) {
                bestPath = new ArrayList<>(path);
            }
        }

        List<Integer> incident = adj[cur];
        for (int ei : incident) {
            if (!used[ei]) {
                used[ei] = true;
                int nxt = edges[ei].other(cur);
                path.add(nxt);
                dfs(nxt, used, len + edges[ei].w, path);
                path.remove(path.size() - 1);
                used[ei] = false;
            }
        }
    }

    static boolean lexLess(List<Integer> a, List<Integer> b) {
        int sz = Math.min(a.size(), b.size());
        for (int i = 0; i < sz; i++) {
            int x = a.get(i), y = b.get(i);
            if (x != y) return x < y;
        }
        return a.size() < b.size();
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        int T = Integer.parseInt(first);

        StringBuilder out = new StringBuilder();

        for (int tc = 1; tc <= T; tc++) {
            n = fs.nextInt();
            m = fs.nextInt();

            edges = new Edge[m];
            adj = new ArrayList[n + 1];
            for (int i = 1; i <= n; i++) adj[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = fs.nextInt();
                int v = fs.nextInt();
                long w = fs.nextLong();
                edges[i] = new Edge(u, v, w);
                adj[u].add(i);
                adj[v].add(i);
            }

            for (int i = 1; i <= n; i++) {
                adj[i].sort((a, b) -> {
                    int oa = edges[a].other(i);
                    int ob = edges[b].other(i);
                    if (oa != ob) return Integer.compare(oa, ob);
                    return Integer.compare(a, b);
                });
            }

            bestLen = -1;
            bestPath = null;
            boolean[] used = new boolean[m];

            for (int start = 1; start <= n; start++) {
                ArrayList<Integer> path = new ArrayList<>();
                path.add(start);
                dfs(start, used, 0L, path);
            }

            if (bestLen < 0) {
                bestLen = 0;
                bestPath = new ArrayList<>();
                bestPath.add(1);
            }

            out.append(bestLen).append('\n');
            for (int i = 0; i < bestPath.size(); i++) {
                if (i > 0) out.append(' ');
                out.append(bestPath.get(i));
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}
